-- =====================================================================
-- Setup · Create the tables the daily jobs write to
-- Schedule: run once by hand
-- Generated by `python -m appchurn.bqml`; edit config.py, not this file.
--
-- at_risk_customers   one row per user per score date, partitioned by
--                     date, so every day's list is kept for monitoring
-- model_registry      every trained model, its test result, and which
--                     one is active
-- model_monitoring    weekly checks of past scores against outcomes
--
-- In the free sandbox, tables and partitions expire after 60 days and
-- scheduled queries, INSERT/DELETE and exports are not available: link a
-- billing account (with a budget alert) before scheduling.
-- =====================================================================

CREATE SCHEMA IF NOT EXISTS `your-project-id.churn_demo`
OPTIONS (location = 'US');

CREATE TABLE IF NOT EXISTS `your-project-id.churn_demo.at_risk_customers` (
  score_date DATE NOT NULL,
  risk_rank INT64,
  user_pseudo_id STRING NOT NULL,
  risk_band STRING,
  churn_probability FLOAT64,
  reasons STRING,
  in_holdout BOOL,
  model_name STRING,
  days_since_last_active INT64,
  active_days_28d INT64,
  events_7d_vs_weekly_avg FLOAT64,
  tenure_days INT64,
  platform STRING,
  country STRING,
  device_category STRING
)
PARTITION BY score_date
CLUSTER BY risk_band;

CREATE TABLE IF NOT EXISTS `your-project-id.churn_demo.model_registry` (
  model_name STRING NOT NULL,
  trained_at TIMESTAMP,
  run_date DATE,
  train_from DATE,
  train_to DATE,
  test_from DATE,
  test_to DATE,
  candidate_roc_auc FLOAT64,
  previous_active_model STRING,
  previous_active_roc_auc FLOAT64,
  rule_roc_auc FLOAT64,
  is_active BOOL,
  decision STRING
);

CREATE TABLE IF NOT EXISTS `your-project-id.churn_demo.model_monitoring` (
  score_date DATE NOT NULL,
  model_name STRING,
  users INT64,
  mean_predicted FLOAT64,
  actual_churn FLOAT64,
  roc_auc FLOAT64,
  rule_roc_auc FLOAT64,
  high_band_churn FLOAT64,
  contacted_churn FLOAT64,
  holdout_churn FLOAT64,
  holdout_users INT64,
  status STRING,
  checked_at TIMESTAMP
)
PARTITION BY score_date;
